using VisionUi;
using System.Text.Json;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using VisionFramework;
using DataGrid=System.Windows.Controls.DataGrid;
using Binding=System.Windows.Data.Binding;
using Button=System.Windows.Controls.Button;
using TextBox=System.Windows.Controls.TextBox;
using ComboBox=System.Windows.Controls.ComboBox;
namespace VisionEditor;
public sealed class GroupComplexEditor:Window{
 readonly GroupRoiEditor? graphicRoi; public GroupRoiEditor? GraphicRoi=>graphicRoi; public VisionCore.GrayImage? RoiImage{set=>graphicRoi?.SetImage(value);}
 readonly NodeDocument node;readonly ModuleDescriptor descriptor;readonly ParameterDescriptor parameter;readonly Action<IReadOnlyDictionary<string,JsonElement>,IReadOnlyList<RoiDocument>?> save;readonly Dictionary<string,TextBox> fields=new();readonly TextBlock error=new(){Foreground=System.Windows.Media.Brushes.DarkRed};readonly ComboBox? choices;
 public GroupComplexEditor(NodeDocument node,ModuleDescriptor descriptor,ParameterDescriptor parameter,Action<IReadOnlyDictionary<string,JsonElement>,IReadOnlyList<RoiDocument>?> save){this.node=node;this.descriptor=descriptor;this.parameter=parameter;this.save=save;var editor=parameter.Editor??throw new InvalidOperationException("Missing editor metadata.");Title=node.Name+" · "+parameter.Name;Width=740;Height=480;WindowStartupLocation=WindowStartupLocation.CenterOwner;ShowInTaskbar=false;FontFamily=new System.Windows.Media.FontFamily("Microsoft YaHei");FontSize=14;var panel=new DockPanel{Margin=new Thickness(14)};var bottom=new DockPanel{LastChildFill=true,Height=40};var confirm=new Button{Content="确定",Tag="GroupComplexConfirm",MinWidth=70};confirm.Click+=(_,_)=>Confirm();var cancel=new Button{Content="取消",MinWidth=70};cancel.Click+=(_,_)=>Close();DockPanel.SetDock(cancel,Dock.Right);bottom.Children.Add(cancel);DockPanel.SetDock(confirm,Dock.Right);bottom.Children.Add(confirm);error.TextWrapping=TextWrapping.Wrap;bottom.Children.Add(error);DockPanel.SetDock(bottom,Dock.Bottom);panel.Children.Add(bottom);
  if(editor.Kind==ParameterEditorKind.Roi){Width=1000;Height=650;graphicRoi=new GroupRoiEditor(node.Rois??[],parameter.Editor.Roi);panel.Children.Add(graphicRoi);}else{var content=new StackPanel();if(editor.Kind==ParameterEditorKind.Enumeration){choices=new ComboBox{ItemsSource=editor.Choices,DisplayMemberPath="Name",Tag="GroupComplexChoices"};var value=node.Parameters.GetValueOrDefault(parameter.Name,parameter.DefaultValue??default);choices.SelectedItem=editor.Choices!.FirstOrDefault(c=>c.Value.ToString()==value.ToString());content.Children.Add(choices);}else foreach(var key in editor.Fields??new[]{parameter.Name}){var row=new DockPanel{Margin=new Thickness(0,8,0,0)};row.Children.Add(new TextBlock{Text=key,Width=150,VerticalAlignment=VerticalAlignment.Center});var spec=descriptor.Parameters.Single(p=>p.Name==key);var input=new TextBox{Tag="GroupComplexField:"+key,Text=node.Parameters.GetValueOrDefault(key,spec.DefaultValue??default).ToString()};fields[key]=input;if(editor.Kind is ParameterEditorKind.File or ParameterEditorKind.Folder){var browse=new Button{Content="浏览",Tag="GroupComplexBrowse"};DockPanel.SetDock(browse,Dock.Right);browse.Click+=(_,_)=>{if(editor.Kind==ParameterEditorKind.File){var d=new Microsoft.Win32.OpenFileDialog{Filter=editor.Filter??"所有文件|*.*"};if(d.ShowDialog(this)==true)input.Text=d.FileName;}else{var d=new Microsoft.Win32.OpenFolderDialog();if(d.ShowDialog(this)==true)input.Text=d.FolderName;}};row.Children.Add(browse);}row.Children.Add(input);content.Children.Add(row);}panel.Children.Add(content);}Content=panel;
 }
 void Confirm(){try{graphicRoi?.CommitPending();var values=new Dictionary<string,JsonElement>();if(choices is not null){if(choices.SelectedItem is not ParameterEditorChoice choice)throw new InvalidOperationException("请选择枚举值。");values[parameter.Name]=choice.Value.Clone();}foreach(var field in fields){var spec=descriptor.Parameters.Single(p=>p.Name==field.Key);object parsed=spec.Kind switch{ParameterKind.Text=>field.Value.Text,ParameterKind.Integer=>int.Parse(field.Value.Text,CultureInfo.InvariantCulture),ParameterKind.Boolean=>bool.Parse(field.Value.Text),_=>double.Parse(field.Value.Text,CultureInfo.InvariantCulture)};values[field.Key]=JsonSerializer.SerializeToElement(parsed);}save(values,parameter.Editor!.Kind==ParameterEditorKind.Roi?graphicRoi!.Regions:null);DialogResult=true;}catch(Exception e){error.Text=e.Message;}}
}
